# region: gather
def gather(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: sift
def sift(xs, floor_=6):
    return [v for v in xs if v >= floor_]

# region: emit
def emit(xs):
    return [v * v for v in xs[1:]]

# region: shape
def shape(xs, floor_=6):
    return [v for v in xs if v >= floor_]

# region: digest
def digest(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: intake
def intake(summary, bar=2):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return intake(digest(shape(emit(sift(gather(raw))))))

